def check_condition(p, k):
    divisor = 8 * p * (p**k) if k==1 else 8*p**k # Simplified divisor for k=1 as requested
    if k != 1:
        return "k must be 1 for this check."

    base_power = 4 * p

    try:
        # Calculate 3^(4p) - 1
        numerator = pow(3, base_power) - 1

        if numerator % divisor == 0:
            return f"Divisible. {p} works."
        else:
            return f"Not divisible. {p} fails."
    except OverflowError:
        return "Calculation overflowed."

# Test primes p = {2, 3, 5} with k=1
for p in [2, 3, 5]:
    result = check_condition(p, 1)
    print(f"p={p}: {result}")
